static void ut_gpio_init(void)
{
    static GPIO_InitTypeDef cfg;
    ut_reset_regs();
    /* cfg.<field> = <a constant of stm32n6xx_hal_gpio.h>; - one line per field the case needs */
    HAL_GPIO_Init(GPIOA, &cfg);
    CHECK("UT-001", (forge_host_gpio.OTYPER & GPIO_OTYPER_OT0) == GPIO_OTYPER_OT0);
}

